var THESES={"AXTI":{"name":"AXT Inc","status":"On track","conv":3,"since":"July 2026","thesis":"Indium phosphide wafers are the base material for every optical laser, and demand is outrunning a small supply base. Revenue and margins are accelerating.","trigger":"China cutting off export permits for its wafers."},"MU":{"name":"Micron Technology","status":"On track","conv":3,"since":"Fall 2025","thesis":"One of three DRAM makers, with most of its 2027 high-bandwidth memory already sold under contract. Cheap on current earnings if the memory cycle holds.","trigger":"Memory contract prices going flat for two months, or all three DRAM makers raising capacity plans at once."},"WULF":{"name":"TeraWulf","status":"Under review","conv":2,"since":"July 2026","thesis":"A former bitcoin miner with a 20-year Anthropic lease in Kentucky. Once the campus is built, it collects rent like infrastructure.","trigger":"The Kentucky debt deal closing on bad terms, or heavy share sales at low prices."},"CRWV":{"name":"CoreWeave","status":"Under review","conv":2,"since":"Winter 2025","thesis":"AI computing sold on multi-year contracts, with a backlog above $100 billion and Nvidia backstopping unused capacity.","trigger":"Its next debt deal priced at bond-scare yields, or a major customer failing to pay."},"MRVL":{"name":"Marvell Technology","status":"On track","conv":2,"since":"June 2026","thesis":"Custom AI chips for the largest cloud companies plus optical chips, and soon Lumentum's lasers through an all-stock merger.","trigger":"Losing a major custom-chip program."},"AAOI":{"name":"Applied Optoelectronics","status":"On track","conv":2,"since":"March 2026","thesis":"A small US optical module maker with its own lasers. Record revenue, with demand expected to outrun capacity into mid-2027.","trigger":"Orders stalling for two straight quarters."},"LITE":{"name":"Lumentum","status":"On track","conv":2,"since":"October 2026","thesis":"A leading maker of lasers for AI networking with years of order visibility. Being acquired by Marvell in an all-stock deal.","trigger":"Co-packaged optics orders slipping, or regulators blocking the Marvell deal."},"ALAB":{"name":"Astera Labs","status":"On track","conv":3,"since":"February 2026","thesis":"Connectivity chips inside AI servers, with more of its content in every new server generation.","trigger":"A larger competitor winning back sockets on new AI platforms."},"VRT":{"name":"Vertiv","status":"On track","conv":2,"since":"June 2026","thesis":"Power and cooling equipment for data centers. Liquid cooling adds new products to every site.","trigger":"Orders and backlog shrinking for two quarters."},"SKHY":{"name":"SK Hynix","status":"On track","conv":2,"since":"July 2026","thesis":"The leader in high-bandwidth memory, supplying most of the HBM for Nvidia's chips.","trigger":"Losing HBM share to Samsung on Nvidia's next platform."},"BE":{"name":"Bloom Energy","status":"On track","conv":2,"since":"July 2026","thesis":"Fuel cells that deliver power on site in months instead of years, now ordered by data center builders.","trigger":"Data center orders slowing, or a cut to its full-year forecast."},"SNDK":{"name":"Sandisk","status":"On track","conv":2,"since":"Fall 2025","thesis":"Flash storage for AI data centers in a disciplined market. A cyclical I've already trimmed hard.","trigger":"Flash contract prices turning down."},"PL":{"name":"Planet Labs","status":"Under review","conv":1,"since":"June 2026","thesis":"A daily satellite image archive that AI can finally read, sold mostly to defense customers.","trigger":"Backlog growth not speeding up by early 2027."},"IREN":{"name":"IREN","status":"On track","conv":2,"since":"Fall 2025","thesis":"Power-ready sites turned into AI cloud capacity, with Microsoft and a frontier AI lab under contract.","trigger":"Deployments slipping, or financing that heavily dilutes shareholders."},"POET":{"name":"POET Technologies","status":"Under review","conv":1,"since":"June 2026","thesis":"Chip-style manufacturing for optical parts. A speculative bet on one big design win.","trigger":"No volume design win by the end of 2026."},"OSS":{"name":"One Stop Systems","status":"Under review","conv":1,"since":"June 2026","thesis":"Rugged AI computers for vehicles and defense systems.","trigger":"No program wins turning into shipments by the end of 2026."},"UAMY":{"name":"United States Antimony","status":"Under review","conv":1,"since":"2025","thesis":"The only integrated US antimony producer. The price half of the thesis broke when China suspended its export ban.","trigger":"China extending its ban suspension past November 27."},"SMR":{"name":"NuScale Power","status":"Closed","conv":0,"since":"January 2026","closed":"Sold June 5 at a loss of about 44%","result":-44,"thesis":"Small modular nuclear reactors to power AI campuses.","trigger":"No firm US order arrived, so the money went elsewhere."},"ONDS":{"name":"Ondas Holdings","status":"Closed","conv":0,"since":"January 2026","closed":"Sold June 15 at a loss of about 15%","result":-15,"thesis":"Drones and private wireless networks.","trigger":"It never earned a write-up, which told me enough."},"NVDA":{"name":"Nvidia","status":"Watching","conv":0,"watch":true,"thesis":"The demand signal for nearly everything I own. Not owned; I hold its suppliers instead.","trigger":"Watching the investigations around its CEO and its data center guidance."},"AVGO":{"name":"Broadcom","status":"Watching","conv":0,"watch":true,"thesis":"Google's custom-chip partner. Not owned.","trigger":"Its December 9 report is my check on Google's reported 2027 chip cut."}};
